<?php foreach($errors??[] as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post" enctype="multipart/form-data"><?=csrfField()?><div class="row g-4"><div class="col-xl-8"><div class="card stat-card"><div class="card-body p-4"><div class="mb-3"><label class="form-label">عنوان الخبر</label><input class="form-control form-control-lg" name="title" required value="<?=e($_POST['title']??$n['title']??'')?>"></div><div class="mb-3"><label class="form-label">الملخص</label><textarea class="form-control" name="summary" rows="3" required><?=e($_POST['summary']??$n['summary']??'')?></textarea></div><div class="mb-3"><label class="form-label">تفاصيل الخبر</label><div class="btn-group btn-group-sm mb-2" data-editor-toolbar><button type="button" class="btn btn-outline-secondary" data-tag="strong">عريض</button><button type="button" class="btn btn-outline-secondary" data-tag="h2">عنوان</button><button type="button" class="btn btn-outline-secondary" data-tag="p">فقرة</button></div><textarea id="details" class="form-control" name="details" rows="16" required><?=e($_POST['details']??$n['details']??'')?></textarea><div class="form-text">يمكن استخدام وسوم HTML البسيطة؛ تُنقّى تلقائيًا.</div></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">عنوان SEO</label><input class="form-control" name="seo_title" value="<?=e($_POST['seo_title']??$n['seo_title']??'')?>"></div><div class="col-md-6 mb-3"><label class="form-label">وصف SEO</label><input class="form-control" name="seo_description" value="<?=e($_POST['seo_description']??$n['seo_description']??'')?>"></div></div></div></div></div><div class="col-xl-4"><div class="card stat-card mb-4"><div class="card-body"><label class="form-label">التصنيف</label><select class="form-select mb-3" name="category_id" required><option value="">اختر التصنيف</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=((string)($_POST['category_id']??$n['category_id']??'')===(string)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label class="form-label">الحالة</label><select class="form-select mb-3" name="status"><?php $allowed=(currentUser()['role']==='author'?['draft'=>'مسودة','pending'=>'إرسال للمراجعة']:['draft'=>'مسودة','pending'=>'قيد المراجعة','published'=>'منشور','archived'=>'مؤرشف']);foreach($allowed as $v=>$l):?><option value="<?=$v?>" <?=($_POST['status']??$n['status']??'draft')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><?php if(currentUser()['role']!=='author'):?><div class="form-check form-switch mb-2"><input class="form-check-input" type="checkbox" name="is_featured" value="1" <?=!empty($_POST['is_featured']??$n['is_featured']??0)?'checked':''?>><label class="form-check-label">خبر مميز</label></div><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="is_breaking" value="1" <?=!empty($_POST['is_breaking']??$n['is_breaking']??0)?'checked':''?>><label class="form-check-label">خبر عاجل</label></div><?php endif;?><button class="btn btn-primary w-100 btn-lg">حفظ الخبر</button></div></div><div class="card stat-card"><div class="card-body"><label class="form-label">الصورة الرئيسية</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/webp" data-image-input><img class="img-fluid rounded mt-3 <?=empty($n['image'])?'d-none':''?>" src="<?=imageUrl($n['image']??null)?>" data-image-preview alt=""></div></div></div></div></form><script>document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{const t=document.getElementById('details'),tag=b.dataset.tag,s=t.selectionStart,e=t.selectionEnd;t.setRangeText('<'+tag+'>'+t.value.slice(s,e)+'</'+tag+'>',s,e,'end');t.focus()});</script>
